const crypto = require("crypto");
const PRAEFIX = {
  event: "evt", task: "tsk", action: "act", approval: "apr",
  evidence: "evd", error: "err", document: "doc", case: "cse", memory: "mem"
};
const ALPHABET = "0123456789ABCDEFGHJKMNPQRSTVWXYZ";

function ulid(zeitMs) {
  let zeit = "";
  let rest = zeitMs;
  for (let i = 0; i < 10; i++) {
    zeit = ALPHABET[rest % 32] + zeit;
    rest = Math.floor(rest / 32);
  }
  const roh = crypto.randomBytes(16);
  let zufall = "";
  for (let i = 0; i < 16; i++) {
    zufall = zufall + ALPHABET[roh[i] % 32];
  }
  return zeit + zufall;
}

const ergebnis = [];
for (const item of $input.all()) {
  const art = item.json.object_kind;
  const kontext = item.json.context_id;
  const teile = Array.isArray(item.json.idempotency_parts) ? item.json.idempotency_parts : [];
  let ok = true;
  let grund = "";
  if (!Object.prototype.hasOwnProperty.call(PRAEFIX, art)) { ok = false; grund = "object_kind unbekannt: " + String(art); }
  else if (!/^[a-z][a-z0-9_]{2,63}$/.test(String(kontext || ""))) { ok = false; grund = "context_id fehlt oder hat kein gueltiges Format"; }
  else if (teile.length === 0) { ok = false; grund = "idempotency_parts fehlt"; }

  if (!ok) {
    ergebnis.push({ json: { generated: false, reason: grund, trace_id: item.json.trace_id || null } });
    continue;
  }

  const kanonisch = [kontext, art].concat(teile.map(function (t) { return String(t); })).join("|");
  const schluessel = crypto.createHash("sha256").update(kanonisch, "utf8").digest("hex");
  ergebnis.push({ json: {
    generated: true,
    object_kind: art,
    object_id: PRAEFIX[art] + "_" + ulid(Date.now()),
    idempotency_key: schluessel,
    canonical_input: kanonisch,
    context_id: kontext,
    reason: "",
    trace_id: item.json.trace_id || null
  } });
}
return ergebnis;
